package com.qboix.app;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.Gravity;import android.widget.*;import java.util.*;
public class GpsRunActivity extends Activity{
 private final int GOLD=Color.rgb(215,181,91),BG=Color.rgb(9,9,13),CARD=Color.rgb(27,27,34),GREY=Color.rgb(165,165,175);private TextView distance,time,pace,status;private Button start,pause,finish;private boolean active,paused,registered;
 private final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){double m=i.getDoubleExtra("distance",0),p=i.getDoubleExtra("pace",0);int sec=i.getIntExtra("seconds",0);active=i.getBooleanExtra("active",active);paused=i.getBooleanExtra("paused",paused);distance.setText(String.format(Locale.getDefault(),"%.2f",m/1000));time.setText(clock(sec));pace.setText(p>0?clock((int)p):"--:--");String msg=i.getStringExtra("message");if(msg!=null)status.setText(msg);start.setEnabled(!active);start.setText("NEW RUN");pause.setEnabled(active);pause.setText(paused?"RESUME":"PAUSE");finish.setEnabled(active);if(msg!=null&&msg.contains("saved"))Toast.makeText(GpsRunActivity.this,"Q-BOIX run saved",Toast.LENGTH_LONG).show();}};
 public void onCreate(Bundle b){super.onCreate(b);ui();}
 private void ui(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(25),dp(22),dp(22));root.setBackgroundColor(BG);root.addView(label("Q-BOIX",GOLD,26,true));TextView head=label("GPS RUN",Color.WHITE,23,true);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,-2);hp.topMargin=dp(20);root.addView(head,hp);status=label("Offline GPS tracking continues when your screen is locked.",GREY,13,false);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=dp(8);root.addView(status,sp);LinearLayout stats=new LinearLayout(this);stats.setOrientation(1);LinearLayout.LayoutParams st=new LinearLayout.LayoutParams(-1,0,1);st.topMargin=dp(22);st.bottomMargin=dp(15);root.addView(stats,st);distance=metric(stats,"0.00","KILOMETRES");time=metric(stats,"00:00","ELAPSED TIME");pace=metric(stats,"--:--","AVG PACE / KM");start=button("START RUN",Color.rgb(55,190,125));root.addView(start,bp());pause=button("PAUSE",GOLD);pause.setEnabled(false);LinearLayout.LayoutParams pp=bp();pp.topMargin=dp(9);root.addView(pause,pp);finish=button("FINISH & SAVE",Color.rgb(220,100,85));finish.setEnabled(false);LinearLayout.LayoutParams fp=bp();fp.topMargin=dp(9);root.addView(finish,fp);start.setOnClickListener(v->requestStart());pause.setOnClickListener(v->command(paused?GpsTrackingService.RESUME:GpsTrackingService.PAUSE));finish.setOnClickListener(v->command(GpsTrackingService.FINISH));setContentView(root);}
 private void requestStart(){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},41);return;}command(GpsTrackingService.START);}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==41){if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)command(GpsTrackingService.START);else status.setText("Location permission is required.");}}
 private void command(String a){Intent i=new Intent(this,GpsTrackingService.class);i.setAction(a);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}
 protected void onStart(){super.onStart();IntentFilter f=new IntentFilter(GpsTrackingService.ACTION);if(Build.VERSION.SDK_INT>=33)registerReceiver(receiver,f,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(receiver,f);registered=true;}
 protected void onStop(){if(registered){unregisterReceiver(receiver);registered=false;}super.onStop();}
 private TextView metric(LinearLayout parent,String v,String cap){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setGravity(Gravity.CENTER);box.setBackground(panel(CARD));TextView n=label(v,GOLD,31,true);n.setGravity(Gravity.CENTER);box.addView(n);TextView c=label(cap,GREY,11,true);c.setGravity(Gravity.CENTER);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.topMargin=dp(5);box.addView(c,cp);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,0,1);p.bottomMargin=dp(8);parent.addView(box,p);return n;}
 private String clock(int s){return String.format(Locale.getDefault(),"%02d:%02d",s/60,s%60);}private Button button(String t,int c){Button b=new Button(this);b.setText(t);b.setTextColor(Color.BLACK);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setBackground(panel(c));return b;}private LinearLayout.LayoutParams bp(){return new LinearLayout.LayoutParams(-1,dp(54));}private TextView label(String t,int c,float z,boolean bold){TextView v=new TextView(this);v.setText(t);v.setTextColor(c);v.setTextSize(z);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}private GradientDrawable panel(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(14));return d;}private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+0.5f);}
}